import{_ as t,o,c as n,a3 as a}from"./chunks/framework.CRbjHCyB.js";const h=JSON.parse('{"title":"Runtime","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Runtime | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/design/runtime"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/design/runtime"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/design/runtime"}]]},"headers":[],"relativePath":"catter/design/runtime.md","filePath":"en/catter/design/runtime.md","lastUpdated":1788608469000}'),i={name:"catter/design/runtime.md"};function r(s,e,c,d,l,m){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h1><p>A runtime is the mechanism by which catter actually captures process creation. Catter is organized around runtimes: scripts do not care how commands are captured, only what capabilities the current runtime provides.</p><h2 id="why-multiple-runtimes" tabindex="-1">Why multiple runtimes <a class="header-anchor" href="#why-multiple-runtimes" aria-label="Permalink to &quot;Why multiple runtimes&quot;">​</a></h2><p>&quot;Intercepting process creation&quot; differs greatly in feasibility and cost across platforms:</p><ul><li><strong>Hooks are the most general</strong>, transparently intercepting any child process creation, but they depend on platform features. For example, macOS restricts <code>DYLD_INSERT_LIBRARIES</code> and requires special development entitlements; Windows has no preload mechanism and relies on DLL injection instead.</li><li><strong>Some scenarios do not need hooks at all</strong>. If a build system honors the <code>CC</code>/<code>CXX</code> environment variable conventions, replacing the compiler is enough to capture every compilation command.</li><li><strong>Some platforms provide dedicated monitoring APIs</strong>, such as macOS Event Stream / Endpoint Security, which can replace or complement hooks.</li></ul><p>For these reasons catter abstracts capture mechanisms as runtimes: one runtime is one capture implementation that exposes a fixed capability description. Scripts adapt to those capabilities instead of assuming a particular runtime exists.</p><h2 id="capability-model" tabindex="-1">Capability model <a class="header-anchor" href="#capability-model" aria-label="Permalink to &quot;Capability model&quot;">​</a></h2><p>The <code>config.runtime</code> object passed to <code>onStart</code> describes the current runtime:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>type</code></td><td>Runtime type: <code>inject</code> / <code>eslogger</code> / <code>env</code></td></tr><tr><td><code>supportActions</code></td><td>Supported script actions (a subset of <code>skip</code> / <code>drop</code> / <code>abort</code> / <code>modify</code>)</td></tr><tr><td><code>supportParentId</code></td><td>Whether captured commands can report a parent command ID (used by command trees, target trees, etc.)</td></tr></tbody></table><h2 id="mechanisms" tabindex="-1">Mechanisms <a class="header-anchor" href="#mechanisms" aria-label="Permalink to &quot;Mechanisms&quot;">​</a></h2><h3 id="inject-implemented-default" tabindex="-1">inject (implemented, default) <a class="header-anchor" href="#inject-implemented-default" aria-label="Permalink to &quot;inject (implemented, default)&quot;">​</a></h3><ul><li><strong>How it works</strong>: a hook shared library is injected into the build system process. It intercepts process creation calls (the <code>execve</code> / <code>posix_spawn</code> family on Unix, <code>CreateProcess</code> on Windows) and rewrites commands so they run through <code>catter-proxy</code>.</li><li><strong>Platforms</strong>: Linux, macOS, Windows.</li><li><strong>Capabilities</strong>: <code>supportActions = [skip, drop, modify]</code>, <code>supportParentId = true</code>.</li><li><strong>Strengths</strong>: recursive capture -- every descendant process is intercepted; captured commands carry the full environment and a parent command ID.</li><li><strong>Limitations</strong>: the implementation relies on platform features (preload / DLL injection). On macOS, <code>DYLD_INSERT_LIBRARIES</code> is restricted by the system and requires special development entitlements; on Windows, DLL injection may conflict with strong signing or security software policies.</li><li><strong>Implementation details</strong>: <a href="./hook-mechanism">Hook mechanism</a>, <a href="./ipc-protocol">IPC protocol</a>.</li></ul><h3 id="env-planned" tabindex="-1">env (planned) <a class="header-anchor" href="#env-planned" aria-label="Permalink to &quot;env (planned)&quot;">​</a></h3><ul><li><strong>How it works</strong>: sets <code>CC</code> / <code>CXX</code> and similar environment variables to redirect compiler invocations to <code>catter-proxy</code> (wrapper mode).</li><li><strong>Use cases</strong>: build systems that honor the standard compiler environment variable conventions can be captured without hooks.</li><li><strong>Expected limitations</strong>: only invocations routed through those environment variables are captured; hard-coded compiler paths and build scripts with inline <code>cc</code> may bypass it; parent command IDs are expected to be unavailable.</li><li><strong>Status</strong>: not implemented yet. Exact capabilities (such as <code>supportActions</code>) will be confirmed when implemented.</li></ul><h3 id="eslogger-planned" tabindex="-1">eslogger (planned) <a class="header-anchor" href="#eslogger-planned" aria-label="Permalink to &quot;eslogger (planned)&quot;">​</a></h3><ul><li><strong>How it works</strong>: uses the macOS Event Stream monitoring API to observe process creation / execution events (side-channel monitoring).</li><li><strong>Use cases</strong>: an alternative on macOS when hooks are restricted by permissions.</li><li><strong>Expected limitations</strong>: macOS only; requires a system-granted monitoring entitlement; how far side-channel monitoring can intervene in execution (<code>modify</code> / <code>drop</code>, for example) is to be confirmed when implemented.</li><li><strong>Status</strong>: not implemented yet.</li></ul><h2 id="capability-matrix" tabindex="-1">Capability matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mechanism</th><th>Platforms</th><th>Capture method</th><th>supportActions</th><th>supportParentId</th><th>Status</th></tr></thead><tbody><tr><td>inject</td><td>Linux / macOS / Windows</td><td>hook intercepting process creation</td><td><code>skip</code> <code>drop</code> <code>modify</code></td><td>yes</td><td>implemented (default)</td></tr><tr><td>env</td><td>cross-platform</td><td><code>CC</code> / <code>CXX</code> environment variables</td><td>TBD</td><td>expected no</td><td>planned</td></tr><tr><td>eslogger</td><td>macOS</td><td>Event Stream API</td><td>TBD</td><td>TBD</td><td>planned</td></tr></tbody></table><h2 id="selecting-and-checking" tabindex="-1">Selecting and checking <a class="header-anchor" href="#selecting-and-checking" aria-label="Permalink to &quot;Selecting and checking&quot;">​</a></h2><ul><li><code>inject</code> is the default and requires no configuration; other mechanisms will be selectable via <code>-m/--mode</code> once available.</li><li>Scripts should not assume a mechanism: check <code>config.runtime.supportActions</code> in <code>onStart</code> and only use actions the current runtime supports.</li><li>When <code>supportParentId = false</code>, <code>CommandData.parent</code> will be absent, and features relying on parent-child relationships (command trees, target trees) need to degrade gracefully.</li></ul>',20)])])}const u=t(i,[["render",r]]);export{h as __pageData,u as default};
